mapper.select:
SELECT id, title, updated_at FROM content WHERE author_id = #{authorId} AND status = 'DRAFT'
AND (updated_at < #{beforeTime} OR (updated_at = #{beforeTime} AND id < #{beforeId}))
ORDER BY updated_at DESC, id DESC LIMIT #{pageSize}

mapper.update:
UPDATE content
SET title = #{title}, body_markdown = #{body}, version = version + 1, updated_at = CURRENT_TIMESTAMP(3)
WHERE  AND version = #{version}

UPDATE content
SET status = 'PUBLISHED',
    published_at = CURRENT_TIMESTAMP(3),
    updated_at = CURRENT_TIMESTAMP(3),
    version = version + 1
WHERE id = #{id}
  AND author_id = #{authorId}
  AND status = 'DRAFT'
  AND version = #{version}
